import { CouldNotConnectToServerException, UnknownNetworkException } from '@game-studio/exceptions';
import { noop } from '@game-studio/utilities';
import { IServerConnection, IServerCommand, ConnectionState, IServerResponse, IWebsocketConnectionOptions, IAutoReconnectConfig, ServerMessageType } from '../types';
import { RealtimeServer } from './server';

export const KEEP_ALIVE_INTERVAL = 45000;
const XML_KEEP_ALIVE_COMMAND: IServerCommand = {
    toPayload() {
        return '<ping />';
    }
};
const JSON_KEEP_ALIVE_COMMAND: IServerCommand = {
    toPayload() {
        return JSON.stringify({ type: 'ping', payload: null });
    }
};

const ABNORMAL_CLOSURE_ERROR_CODE = 1006;
const DEFAULT_RECONNECT_MAX_RETRIES = 15;
const DEFAULT_RECONNECT_ATTEMPT_TIMEOUT = 3000;
// how long a reconnected socket must stay open before we trust it and reset the retry budget
const DEFAULT_STABLE_CONNECTION_THRESHOLD = 5000;
// how many opened-then-quickly-closed sockets in a row before we conclude the server is refusing the connection
const DEFAULT_MAX_UNSTABLE_CONNECTIONS = 5;

export class WebSocketConnection implements IServerConnection {
    public serverUrl: string;
    public connectionState: ConnectionState = ConnectionState.DISCONNECTED;
    public unhandledDisconnection?: boolean;
    private socket: WebSocket;
    private messageBuffer: string;
    private keepAliveIntervalId?: number;
    private timeoutIntervalId?: number;
    private reconnectionAttempts: number = 0;
    private readonly connectionTimeout: number;
    private readonly maxReconnectionAttempts: number;
    private readonly useTimeout: boolean = false;
    private readonly partialMessages: boolean = true;
    private readonly format: ServerMessageType = 'xml';
    private readonly server: RealtimeServer;
    private errorOccured: boolean = false;
    private forceSocketClose: boolean;

    private autoReconnectEnabled: boolean = false;
    private autoReconnectMaxRetries: number = DEFAULT_RECONNECT_MAX_RETRIES;
    private autoReconnectAttemptTimeout: number = DEFAULT_RECONNECT_ATTEMPT_TIMEOUT;
    private autoReconnectAttempt: number = 0;
    private autoReconnectTimeoutId?: number;
    private stableConnectionTimeoutId?: number;
    private stableConnectionThreshold: number = DEFAULT_STABLE_CONNECTION_THRESHOLD;
    private autoReconnectMaxUnstable: number = DEFAULT_MAX_UNSTABLE_CONNECTIONS;
    private unstableConnectionCount: number = 0;
    private autoReconnectGeneration: number = 0;
    private mIsReconnecting: boolean = false;
    private manualDisconnect: boolean = false;
    private destroyed: boolean = false;
    private reconnectPaused: boolean = false;
    private reconnectPending: boolean = false;

    public get connected() {
        return (this.connectionState & ConnectionState.CONNECTED) === ConnectionState.CONNECTED;
    }

    public get isReconnecting(): boolean {
        return this.mIsReconnecting;
    }

    public get readyState(): number {
        return this.socket.readyState;
    }

    constructor(server: RealtimeServer, options: IWebsocketConnectionOptions) {
        if (options.connectionTimeout !== undefined) {
            this.useTimeout = true;
            this.connectionTimeout = options.connectionTimeout.timeout;
            this.maxReconnectionAttempts = options.connectionTimeout.maxConnectionAttempts;
        }

        if (options.partialMessages !== undefined) {
            this.partialMessages = options.partialMessages;
        }

        if (options.autoReconnect) {
            this.autoReconnectEnabled = true;
            if (typeof options.autoReconnect === 'object') {
                this.autoReconnectMaxRetries = options.autoReconnect.maxRetries ?? DEFAULT_RECONNECT_MAX_RETRIES;
                this.autoReconnectAttemptTimeout = options.autoReconnect.attemptTimeout ?? DEFAULT_RECONNECT_ATTEMPT_TIMEOUT;
                this.autoReconnectMaxUnstable = options.autoReconnect.maxUnstableConnections ?? DEFAULT_MAX_UNSTABLE_CONNECTIONS;
                this.stableConnectionThreshold = options.autoReconnect.stableConnectionThreshold ?? DEFAULT_STABLE_CONNECTION_THRESHOLD;
            }
        }

        this.forceSocketClose = options.forceSocketClose;
        this.server = server;
        this.serverUrl = options.serverUrl;
        this.format = options.format;
        this.messageBuffer = '';
        this.unhandledDisconnection = undefined;
    }

    public connect(): Promise<void> {
        this.manualDisconnect = false;
        this.reconnectPending = false;
        this.cancelReconnect();
        return this.awaitConnected(this.createSocket());
    }

    private createSocket(): WebSocket {
        const socket = new WebSocket(this.serverUrl);
        this.socket = socket;
        // clear any partial frame left over from a dropped connection so it can't corrupt the first message
        this.messageBuffer = '';
        this.unhandledDisconnection = undefined;
        this.broadcastNewConnectionState(ConnectionState.CONNECTING);
        return socket;
    }

    private awaitConnected(socket: WebSocket): Promise<void> {
        return new Promise((resolve, reject) => {
            socket.onopen = () => {
                socket.onmessage = (response) => this.onMessage(response);
                socket.onerror = () => this.errorOccured = true;
                socket.onclose = this.onClose.bind(this);
                this.broadcastNewConnectionState(ConnectionState.CONNECTED);
                this.startKeepAlive();
                // socket is confirmed open; it must now survive the stability threshold or its close counts as the server bouncing us
                this.startStableConnectionTimer();

                if (this.useTimeout) {
                    this.messageTimeout();
                }

                resolve();
            };
            socket.onclose = () => {
                this.stopKeepAlive();

                if (this.useTimeout) {
                    this.stopMessageTimeout();
                }

                this.broadcastNewConnectionState(ConnectionState.DISCONNECTED);
                reject(this.getErrorStatus());
            };
        });
    }

    public send(command: IServerCommand): void {
        if (this.socket.readyState === WebSocket.OPEN) {
            this.socket.send(command.toPayload());
        } else {
            this.onError(this.getErrorStatus());
        }
    }

    public disconnect(): Promise<void> {
        // an explicit disconnect is a user intent to stay down, so any reconnect loop must halt
        this.manualDisconnect = true;
        this.reconnectPending = false;
        this.cancelReconnect();

        if ([ConnectionState.DISCONNECTING, ConnectionState.DISCONNECTED].includes(this.connectionState)) {
            return Promise.resolve();
        }

        this.broadcastNewConnectionState(ConnectionState.DISCONNECTING);

        if (this.socket) {
            this.unhandledDisconnection = false;
        }

        this.stopKeepAlive();
        this.stopMessageTimeout();

        if (!this.socket) {
            return Promise.resolve();
        } else {
            return this.waitForDisconnectedState();
        }
    }

    public destroy(): void {
        this.destroyed = true;
        this.manualDisconnect = true;
        this.reconnectPending = false;
        this.cancelReconnect();
        this.stopKeepAlive();
        this.stopMessageTimeout();
        this.detachSocket(true);
        this.connectionState = ConnectionState.DISCONNECTED;
    }

    public enableAutoReconnect(config: IAutoReconnectConfig = {}): void {
        this.autoReconnectEnabled = true;
        this.autoReconnectMaxRetries = config.maxRetries ?? this.autoReconnectMaxRetries;
        this.autoReconnectAttemptTimeout = config.attemptTimeout ?? this.autoReconnectAttemptTimeout;
        this.autoReconnectMaxUnstable = config.maxUnstableConnections ?? this.autoReconnectMaxUnstable;
        this.stableConnectionThreshold = config.stableConnectionThreshold ?? this.stableConnectionThreshold;
    }

    public disableAutoReconnect(): void {
        this.autoReconnectEnabled = false;
        this.cancelReconnect();
    }

    // stop retrying (e.g. while backgrounded) but remember a pending drop so resume can pick it back up
    public pauseReconnect(): void {
        this.reconnectPaused = true;
        if (this.mIsReconnecting) {
            this.cancelReconnect();
            this.reconnectPending = true;
        }
    }

    public resumeReconnect(): void {
        this.reconnectPaused = false;
        if (this.reconnectPending) {
            this.reconnectPending = false;
            this.maybeStartReconnect();
        }
    }

    private onMessage(event: MessageEvent): void {
        this.startKeepAlive();

        if (this.useTimeout) {
            this.reconnectionAttempts = 0;
            this.messageTimeout();
        }

        if (this.partialMessages) {
            this.broadcastNewConnectionState(ConnectionState.CONNECTED);

            this.messageBuffer += event.data;
            const partialMessage: string = this.messageBuffer.substring(this.messageBuffer.lastIndexOf('\0'));
            const messages: string = this.messageBuffer.substring(0, this.messageBuffer.lastIndexOf('\0'));
            messages.split(/\0/).forEach((message) => {
                const response: IServerResponse = {
                    Contents: message.replace(/\0|\r?\n|\r/g, '')
                };

                this.server.emit('response', response);
            });

            this.messageBuffer = partialMessage;
        } else {
            this.server.emit('response', { Contents: event.data });
        }
    }

    private getErrorStatus(): Error {
        if (this.socket.readyState !== WebSocket.OPEN) {
            return new CouldNotConnectToServerException();
        }

        return new UnknownNetworkException();
    }

    private onError(error: Error) {
        if (![ConnectionState.DISCONNECTING, ConnectionState.DISCONNECTED].includes(this.connectionState)) {
            this.server.emit('error', error);
        }
    }

    private onClose(event: CloseEvent) {
        if (this.errorOccured) {
            if (event.code !== ABNORMAL_CLOSURE_ERROR_CODE) {
                this.onError(this.getErrorStatus());
            }
        }
        this.errorOccured = false;
        this.detachSocket(false);

        if (this.unhandledDisconnection === undefined) {
            this.unhandledDisconnection = true;
        }

        this.broadcastNewConnectionState(ConnectionState.DISCONNECTED);
        this.stopKeepAlive();
        this.stopMessageTimeout();
        this.registerConnectionClose();
        this.maybeStartReconnect();
    }

    private waitForDisconnectedState() {
        return new Promise<void>((resolve) => {
            const onConnectionStateChange = (state: ConnectionState) => {
                if (state === ConnectionState.DISCONNECTED) {
                    this.server.off('state', onConnectionStateChange);
                    resolve();
                }
            };

            this.server.on('state', onConnectionStateChange);
            this.socket.close();

            if (this.forceSocketClose) {
                // We force the on close callback because of bugs in browsers like this:
                // https://bugs.webkit.org/show_bug.cgi?id=247943
                this.onClose(new CloseEvent(''));
            }
        });
    }

    private startKeepAlive() {
        this.stopKeepAlive();
        this.keepAliveIntervalId = window.setInterval(() => {
            if (this.socket.readyState === WebSocket.OPEN) {
                this.send(this.format === 'xml' ? XML_KEEP_ALIVE_COMMAND : JSON_KEEP_ALIVE_COMMAND);
            }
        }, KEEP_ALIVE_INTERVAL);
    }

    private stopKeepAlive() {
        window.clearInterval(this.keepAliveIntervalId);
    }

    private messageTimeout() {
        this.stopMessageTimeout();
        this.timeoutIntervalId = window.setInterval(() => {
            if (this.reconnectionAttempts < this.maxReconnectionAttempts) {
                this.broadcastNewConnectionState(ConnectionState.SLOW_CONNECTION);
                this.reconnectionAttempts++;
            } else {
                this.handleConnectionLost();
            }
        }, this.connectionTimeout);
    }

    private stopMessageTimeout() {
        window.clearInterval(this.timeoutIntervalId);
    }

    private broadcastNewConnectionState(state: ConnectionState) {
        if (state === this.connectionState) {
            return;
        }
        if (this.connectionState === ConnectionState.DISCONNECTED && state === ConnectionState.CONNECTED) {
            // shouldn't be trying to plumb us into connected when we've disconnected
            return;
        }

        this.connectionState = state;
        this.server.emit('state', state);
    }

    // the message-timeout has decided the socket is dead; settle to disconnected then let the reconnect loop take over
    private handleConnectionLost(): void {
        this.reconnectionAttempts = 0;
        this.stopKeepAlive();
        this.stopMessageTimeout();
        this.unhandledDisconnection = false;
        this.detachSocket(true);
        this.broadcastNewConnectionState(ConnectionState.CONNECTION_LOST);
        this.broadcastNewConnectionState(ConnectionState.DISCONNECTED);
        this.maybeStartReconnect();
    }

    private maybeStartReconnect(): void {
        if (!this.autoReconnectEnabled || this.manualDisconnect || this.destroyed || this.connected) {
            return;
        }
        if (this.reconnectPaused) {
            this.reconnectPending = true;
            return;
        }
        this.startReconnect();
    }

    private startReconnect(): void {
        if (this.mIsReconnecting) {
            return;
        }
        this.mIsReconnecting = true;
        this.attemptReconnect(this.autoReconnectGeneration);
    }

    // bumping the generation invalidates any in-flight attempt so a manual connect/disconnect can preempt it cleanly
    private cancelReconnect(): void {
        this.stopStableConnectionTimer();
        this.autoReconnectGeneration++;
        this.mIsReconnecting = false;
        this.autoReconnectAttempt = 0;
        this.unstableConnectionCount = 0;
        if (this.autoReconnectTimeoutId !== undefined) {
            window.clearTimeout(this.autoReconnectTimeoutId);
            this.autoReconnectTimeoutId = undefined;
        }
    }

    private async attemptReconnect(generation: number): Promise<void> {
        if (generation !== this.autoReconnectGeneration) {
            return;
        }

        this.autoReconnectAttempt++;

        const tooManyUnstable = this.autoReconnectMaxUnstable > 0 && this.unstableConnectionCount >= this.autoReconnectMaxUnstable;
        if (this.autoReconnectAttempt > this.autoReconnectMaxRetries || tooManyUnstable) {
            this.mIsReconnecting = false;
            this.broadcastNewConnectionState(ConnectionState.RETRY_CIRCUIT_BROKEN);
            return;
        }

        this.server.emit('reconnectAttempt', this.autoReconnectAttempt);

        const socket = this.createSocket();

        try {
            await Promise.race([this.awaitConnected(socket), this.autoReconnectTimeout()]);

            if (generation !== this.autoReconnectGeneration) {
                this.closeSocketRef(socket);
                return;
            }

            this.mIsReconnecting = false;
            this.server.emit('reconnect');
            this.server.emit('reconnectSuccess');
        } catch {
            this.closeSocketRef(socket);

            if (generation !== this.autoReconnectGeneration) {
                return;
            }

            this.autoReconnectTimeoutId = window.setTimeout(() => this.attemptReconnect(generation), this.autoReconnectAttemptTimeout);
        }
    }

    private autoReconnectTimeout(): Promise<never> {
        return new Promise((_, reject) => {
            window.setTimeout(() => reject(), this.autoReconnectAttemptTimeout);
        });
    }

    // once a socket stays open past the threshold we trust it and clear both the retry budget and the unstable streak
    private startStableConnectionTimer(): void {
        if (!this.autoReconnectEnabled) {
            return;
        }
        this.stopStableConnectionTimer();
        this.stableConnectionTimeoutId = window.setTimeout(() => {
            this.stableConnectionTimeoutId = undefined;
            this.autoReconnectAttempt = 0;
            this.unstableConnectionCount = 0;
        }, this.stableConnectionThreshold);
    }

    private stopStableConnectionTimer(): void {
        if (this.stableConnectionTimeoutId !== undefined) {
            window.clearTimeout(this.stableConnectionTimeoutId);
            this.stableConnectionTimeoutId = undefined;
        }
    }

    // a socket closing while still pending stability means the server accepted then dropped us — count it as an unstable connection
    private registerConnectionClose(): void {
        if (this.stableConnectionTimeoutId !== undefined) {
            this.unstableConnectionCount++;
        }
        this.stopStableConnectionTimer();
    }

    private detachSocket(close: boolean): void {
        if (!this.socket) {
            return;
        }
        this.closeSocketRef(this.socket, close);
    }

    private closeSocketRef(socket: WebSocket, close: boolean = true): void {
        socket.onopen = noop;
        socket.onerror = noop;
        socket.onmessage = noop;
        socket.onclose = noop;
        if (close) {
            try {
                socket.close();
            } catch {
                /* socket may already be closed */
            }
        }
    }
}
